<script setup lang="ts">
import {computed} from 'vue'
import type { ChannelMonitorGroupModelConfig } from '../types/channelMonitor'
const props = defineProps<{modelValue: ChannelMonitorGroupModelConfig[];groups: {groupId: string;groupName:string}[]}>()
const emit = defineEmits<{ 'update:modelValue': [ChannelMonitorGroupModelConfig[]] }>()
const rows=computed(()=>props.modelValue.map((row,index)=>({row,index})).filter(({row,index})=>props.modelValue.findIndex(v=>v.groupId===row.groupId)===index))
function add() { const g=props.groups.find(g=>!props.modelValue.some(v=>v.groupId===g.groupId));if(!g)return;emit('update:modelValue',[...props.modelValue,{groupId:g.groupId,groupName:g.groupName,modelId:'',mode:'text',intervalMinutes:2}]) }
function change(index:number, field:string, value:string) {const next=props.modelValue.map(v=>({...v}));const row=next[index];if(!row)return;if(field==='intervalMinutes'||field==='seconds') (row as any)[field]=Math.max(0,Number(value)||0);else (row as any)[field]=value;if(field==='groupId')row.groupName=props.groups.find(g=>g.groupId===value)?.groupName||'';if(field==='mode')row.intervalMinutes=value==='video'?30:value==='audio'||value==='image'?10:2;emit('update:modelValue',next)}
const protocols: Record<string,string[]>={image:['openai_image','gemini_image','sub2api_async_image','yunfei_gemini_native'],video:['openai_video','newapi_video','ark_native','v6k_video_gateway'],audio:['sub2api_audio','sub2api_speech','openai_tts','openai_transcription','audio_chat']}
</script>
<template><section class="my-4 space-y-3 rounded-xl border border-border/50 bg-surface p-4"><div class="flex justify-between"><h3 class="font-medium">主动检测模型</h3><button type="button" class="text-sm text-primary" @click="add">添加分组模型</button></div><p class="text-xs text-muted-foreground">每组检测一个模型，仅在开启主动检测后调用；默认只获取上游状态。</p><div class="max-h-72 space-y-3 overflow-auto"><div v-for="{row,index} in rows" :key="index" class="flex flex-wrap gap-2 rounded border border-border/40 p-2 text-xs"><select :value="row.groupId" class="max-w-48 rounded border bg-background p-1" @change="change(index,'groupId',($event.target as HTMLSelectElement).value)"><option v-for="g in groups" :key="g.groupId" :value="g.groupId" :disabled="g.groupId!==row.groupId&&modelValue.some(v=>v.groupId===g.groupId)">{{g.groupName}}</option></select><input :value="row.modelId" class="w-44 rounded border bg-background p-1" placeholder="模型 ID" @input="change(index,'modelId',($event.target as HTMLInputElement).value)" /><select :value="row.mode||'text'" class="rounded border bg-background p-1" @change="change(index,'mode',($event.target as HTMLSelectElement).value)"><option value="text">文本</option><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select><select v-if="row.mode && protocols[row.mode]" :value="row.adapter||''" class="rounded border bg-background p-1" @change="change(index,'adapter',($event.target as HTMLSelectElement).value)"><option value="">按模型预设</option><option v-for="p in protocols[row.mode]" :key="p" :value="p">{{p}}</option></select><label>周期（分钟）<input :value="row.intervalMinutes||0" type="number" min="0" max="1440" class="ml-1 w-16 rounded border bg-background p-1" @input="change(index,'intervalMinutes',($event.target as HTMLInputElement).value)" /></label><input v-if="row.mode==='video'" :value="row.seconds||4" type="number" min="1" class="w-16 rounded border bg-background p-1" aria-label="视频秒数" @input="change(index,'seconds',($event.target as HTMLInputElement).value)" /><button type="button" class="text-red-500" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))">移除</button></div></div></section></template>
